static void resolution(){int i=(int)SendMessageW(resCombo,CB_GETCURSEL,0,0);int ow=i==0?1920:i==1?1600:i==2?1280:3840,oh=i==0?1080:i==1?900:i==2?720:2160;int q=(int)SendMessageW(scaleCombo,CB_GETCURSEL,0,0);float s=q==0?1.f:q==1?.875f:q==2?.75f:q==3?2.f/3.f:q==4?.5f:1.f;unsigned samples=(q==5)?16u:1u;{std::lock_guard<std::mutex>l(reqMutex);outW=ow;outH=oh;renderW=(int)std::lround(ow*s);renderH=(int)std::lround(oh*s);samplesPerPixel=samples;}requestRender();}
